// ---- the tail the mechanical scan can't reach: computed / negative / aliased /
// zero-valued enum members / ole32-private defines. Each cited to its source. ----

/// wtypes.h enum TYMED — the zero member (the scan only matches `NAME = <lit>,`
/// forms that carry a trailing comma; TYMED_NULL is the enum's first entry).
pub const TYMED_NULL: DWORD = 0;
/// objidl.h enum MKRREDUCE — MKRREDUCE_ALL is 0
pub const MKRREDUCE_ALL: DWORD = 0;
/// objidl.h enum LOCKTYPE
pub const LOCK_ONLYONCE: DWORD = 4;

/// winuser.h: `#define CW_USEDEFAULT ((int)0x80000000)` — SIGNED, so it must be i32.
/// Passing it as a u32 to CreateWindowEx's c_int params is a type error, and coercing
/// it through `as` from an unsigned const would be a silent sign flip.
pub const CW_USEDEFAULT: c_int = 0x8000_0000u32 as i32;
/// winuser.h: `#define GWL_EXSTYLE (-20)`
pub const GWL_EXSTYLE: c_int = -20;

/// fileapi.h: `#define INVALID_FILE_ATTRIBUTES ((DWORD)-1)`
pub const INVALID_FILE_ATTRIBUTES: DWORD = 0xFFFF_FFFF;
/// handleapi.h: `#define INVALID_HANDLE_VALUE ((HANDLE)(-1))`
pub const INVALID_HANDLE_VALUE: HANDLE = usize::MAX as HANDLE;

/// memoryapi.h: FILE_MAP_READ = SECTION_MAP_READ (0x0004),
/// FILE_MAP_WRITE = SECTION_MAP_WRITE (0x0002)
pub const FILE_MAP_READ: DWORD = 0x0004;
pub const FILE_MAP_WRITE: DWORD = 0x0002;

/// rpcnterr.h: RPC_X_NO_MEMORY = RPC_S_OUT_OF_MEMORY (14),
